'use strict';
const $=s=>document.querySelector(s);
let tracks=[],selected=null,activeFilter='all',localAudioUrl=null;
const audio=$('#audio');
const descriptions={shelf:'レコードを手に取るように、一曲ずつ。',editorial:'曲の背景を読む、音楽雑誌のように。',minimal:'余白と文字で、時間の流れをたどる。'};
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
function render(){const list=$('#tracks');list.replaceChildren();const visible=tracks.filter(t=>activeFilter==='all'||t.historyEventId===activeFilter);$('#count').textContent=String(visible.length).padStart(2,'0')+' TRACKS';for(const [i,t] of visible.entries()){const article=el('article',undefined,'track');const art=el('button',undefined,'cover '+t.art);art.type='button';art.setAttribute('aria-label',t.title+'の詳細を開く');const num=el('span',String(tracks.indexOf(t)+1).padStart(2,'0'),'cover-number');const artTitle=el('span',t.title,'cover-title');art.append(num,artTitle,el('span','MUSIC ARCHIVE','cover-caption'));art.addEventListener('click',()=>openDetail(t));const content=el('div',undefined,'track-copy');content.append(el('p',t.displayPeriod,'eyebrow'));const h=el('h3');const link=el('button',t.title,'title-button');link.addEventListener('click',()=>openDetail(t));h.append(link);content.append(h,el('p',t.notesThen||t.displayPeriod+'に作った曲。','excerpt'));const actions=el('div',undefined,'track-actions');const play=el('button','▶ 音源を試す','play-button');play.setAttribute('aria-label',t.title+'を選択して音源を試す');play.addEventListener('click',()=>selectTrack(t));const notes=el('button','ライナーノーツ ↗','notes-button');notes.addEventListener('click',()=>openDetail(t));actions.append(play,notes);if(t.sourceUrl){const a=el('a','Sunoで聴く ↗','notes-button');a.href=t.sourceUrl;a.target='_blank';a.rel='noopener noreferrer';actions.append(a);}content.append(actions);article.append(art,content);list.append(article);}}
function releaseAudio(){audio.pause();audio.removeAttribute('src');audio.load();if(localAudioUrl){URL.revokeObjectURL(localAudioUrl);localAudioUrl=null;}$('#audio-file').value='';}
function selectTrack(t){if(selected?.id!==t.id){releaseAudio();selected=t;audio.hidden=!t.audioSrc;$('#audio-status').textContent=t.audioSrc?'登録音源':'音源未登録 · 手元の音源で操作を試せます';if(t.audioSrc)audio.src=t.audioSrc;}$('#playing-title').textContent=t.title;$('#player').hidden=false;document.body.classList.add('has-player');}
function setPanel(panel){if(panel==='lyrics'&&!selectedDetail?.lyricsByOwner)return;$('#notes-panel').hidden=panel!=='notes';$('#lyrics-panel').hidden=panel!=='lyrics';document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel===panel)));}
let selectedDetail=null;
function openDetail(t){selectedDetail=t;$('#detail-period').textContent=t.displayPeriod;$('#detail-title').textContent=t.title;$('#detail-art').className='cover '+t.art;$('#credits').textContent='作曲：'+t.composer+(t.lyricist?' ／ 作詞：'+t.lyricist:' ／ 作詞：未確認')+(t.audioVersionYear?' ／ 音源制作：'+t.audioVersionYear:'');$('#notes-then').textContent=t.notesThen||'曲ごとのノーツは、これから。時代の背景は年表の「時代のノーツ」で読めます。';$('#notes-now').textContent=t.notesNow||'現在の音源や、今聴いて感じることを追記します。';const source=$('#detail-source');source.hidden=!t.sourceUrl;if(t.sourceUrl)source.href=t.sourceUrl;const creditNote=$('#lyric-status');creditNote.textContent=t.lyricCreditStatus==='unconfirmed'?'作詞者は未確認です。本人作詞と確認できた曲だけ歌詞を掲載します。':'作詞：'+t.lyricist+'。本人が作詞していない曲の歌詞は掲載しません。';const lyricsButton=$('[data-panel="lyrics"]');lyricsButton.hidden=!t.lyricsByOwner||!t.lyrics;$('#lyrics').textContent=t.lyricsByOwner?(t.lyrics||''):'';setPanel('notes');$('#detail').showModal();}
$('#detail-play').addEventListener('click',()=>{selectTrack(selectedDetail);$('#detail').close();$('.audio-upload input').focus();});
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close();}});
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
document.querySelectorAll('[data-design]').forEach(b=>b.addEventListener('click',()=>{document.body.dataset.theme=b.dataset.design;document.querySelectorAll('[data-design]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#design-description').textContent=descriptions[b.dataset.design];document.querySelector('meta[name="theme-color"]').content=b.dataset.design==='editorial'?'#182522':'#f3efe6';}));
$('#close-player').addEventListener('click',()=>{releaseAudio();selected=null;$('#player').hidden=true;document.body.classList.remove('has-player');});
$('#audio-file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('audio/')){$('#audio-status').textContent='音声ファイルを選んでください';return;}audio.pause();if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);localAudioUrl=URL.createObjectURL(f);audio.src=localAudioUrl;audio.hidden=false;$('#audio-status').textContent='端末内の試聴：'+f.name;});
audio.addEventListener('error',()=>{$('#audio-status').textContent='この音源を再生できません。別の形式をお試しください。';});
window.addEventListener('pagehide',()=>{if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);});
async function init(){try{const r=await fetch('tracks.json');if(!r.ok)throw Error('tracks');tracks=await r.json();const filters=$('#filters');for(const value of ['all',...new Set(tracks.map(t=>t.historyEventId))]){const b=el('button',value==='all'?'すべて':tracks.find(t=>t.historyEventId===value).displayPeriod);b.setAttribute('aria-pressed',String(value==='all'));b.addEventListener('click',()=>{activeFilter=value;filters.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();});filters.append(b);}render();await initHistory();}catch{$('#error').hidden=false;$('#error').textContent='曲データを読み込めませんでした。ページを再読み込みしてください。';}}
async function initHistory(){try{const r=await fetch('history.json');if(!r.ok)throw Error('history');const data=await r.json();for(const e of data){const li=el('li');const period=el('p',e.period,'eyebrow');const content=el('div');content.append(el('h3',e.title),el('p',e.description));if(e.id!=='birth'){const notes=el('details',undefined,'era-notes');notes.append(el('summary','時代のノーツ'));const fields=[['musicPlayed','やっていた音楽'],['musicListenedTo','聴いていた音楽'],['creativeMindset','曲を作るときの気持ち'],['reflectionNow','今、振り返って'],['reworkingNow','今、再制作して']];let populated=false;for(const [key,label] of fields){if(e.eraNotes?.[key]){notes.append(el('h4',label),el('p',e.eraNotes[key]));populated=true;}}if(!populated){notes.append(el('p','この時代のノーツは、これから。曲がなくても、聴いていた音楽や曲を作るときの気持ちを残せます。','empty-note'));}content.append(notes);}if(e.trackIds?.length){const related=el('div',undefined,'era-tracks');related.append(el('span','この時期の曲','eyebrow'));for(const id of e.trackIds){const t=tracks.find(t=>t.id===id);if(t){const b=el('button',t.title+' ↗','related-song');b.addEventListener('click',()=>openDetail(t));related.append(b);}}content.append(related);}li.append(period,content);$('#history-list').append(li);}}catch{$('#history-list').append(el('li','経歴を読み込めませんでした。ページを再読み込みしてください。'));}}
init();
